    /// <summary>Get the battery state of a gamepad.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetGamepadPowerInfo</c>.</para>
    /// <para>
    /// You should never take a battery status as absolute truth. Batteries (especially failing batteries) are delicate
    /// hardware, and the values reported here are best estimates based on what that hardware reports. It's not uncommon
    /// for older batteries to lose stored power much faster than it reports, or completely drain when reporting it has
    /// 20 percent left, etc.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="gamepad">the gamepad object to query.</param>
    /// <param name="percent">
    /// a pointer filled in with the percentage of battery life left, between 0 and 100, or NULL to ignore. This will be
    /// filled in with -1 we can't determine a value or there is no battery.
    /// </param>
    /// <returns>the current battery state.</returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_GetGamepadPowerInfo")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial PowerState GetGamepadPowerInfo(Gamepad gamepad, int* percent);

    /// <summary>Get the battery state of a gamepad.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetGamepadPowerInfo</c>.</para>
    /// <para>
    /// You should never take a battery status as absolute truth. Batteries (especially failing batteries) are delicate
    /// hardware, and the values reported here are best estimates based on what that hardware reports. It's not uncommon
    /// for older batteries to lose stored power much faster than it reports, or completely drain when reporting it has
    /// 20 percent left, etc.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="gamepad">the gamepad object to query.</param>
    /// <param name="percent">
    /// a pointer filled in with the percentage of battery life left, between 0 and 100, or NULL to ignore. This will be
    /// filled in with -1 we can't determine a value or there is no battery.
    /// </param>
    /// <returns>the current battery state.</returns>
    public static PowerState GetGamepadPowerInfo(Gamepad gamepad, out int percent)
    {
        percent = default;
        fixed (int* percentPtr = &percent)
        {
            return GetGamepadPowerInfo(gamepad, percentPtr);
        }
    }

    /// <summary>Check if a gamepad has been opened and is currently connected.</summary>
