    /// <para>Binds <c>SDL_GetGamepadTouchpadFinger</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GetNumGamepadTouchpadFingers</c>.</para>
    /// </remarks>
    /// <param name="gamepad">a gamepad.</param>
    /// <param name="touchpad">a touchpad.</param>
    /// <param name="finger">a finger.</param>
    /// <param name="down">a pointer filled with true if the finger is down, false otherwise, may be NULL.</param>
    /// <param name="x">
    /// a pointer filled with the x position, normalized 0 to 1, with the origin in the upper left, may be NULL.
    /// </param>
    /// <param name="y">
    /// a pointer filled with the y position, normalized 0 to 1, with the origin in the upper left, may be NULL.
    /// </param>
    /// <param name="pressure">a pointer filled with pressure value, may be NULL.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public static bool GetGamepadTouchpadFinger(Gamepad gamepad, int touchpad, int finger, out bool down, out float x, out float y, out float pressure)
    {
        down = default;
        x = default;
        y = default;
        pressure = default;
        fixed (bool* downPtr = &down)
        fixed (float* xPtr = &x)
        fixed (float* yPtr = &y)
        fixed (float* pressurePtr = &pressure)
        {
            return GetGamepadTouchpadFinger(gamepad, touchpad, finger, downPtr, xPtr, yPtr, pressurePtr);
        }
    }

